-- Tarkaari database setup: all migrations + catalogue seed (generated by scripts/bundle-sql.mjs).
-- Paste into Supabase → SQL Editor on a NEW project and press Run. Takes a few seconds.
-- Re-running on a project that already has the tables stops with a clear message and changes nothing.

do $$
begin
  if to_regclass('public.users') is not null then
    raise exception 'Tarkaari is already set up in this project (public.users exists). Nothing was changed.';
  end if;
end $$;


-- ===== 20261018000001_schema.sql =====
-- Tarakari core schema.
-- Money is numeric(10,2) rupees; quantities are numeric(8,3) in the item's unit.

create extension if not exists pg_trgm with schema extensions;

-- ---------------------------------------------------------------------------
-- Enums
-- ---------------------------------------------------------------------------
create type public.user_role as enum ('customer', 'vendor', 'admin');
create type public.user_status as enum ('active', 'blocked');
create type public.app_language as enum ('en', 'kn');
create type public.apartment_status as enum ('active', 'merged', 'removed');
create type public.vendor_approval as enum ('pending', 'active', 'paused', 'blocked');
create type public.payment_mode as enum ('per_delivery', 'monthly');
create type public.payment_method as enum ('upi', 'cash');
create type public.item_unit as enum ('kg', 'g', 'piece', 'bunch', 'packet');
create type public.item_category as enum ('daily', 'vegetables', 'roots', 'leafy', 'other');
create type public.reason_tag as enum ('morning_market', 'farm_fresh', 'organic', 'seasonal');
create type public.order_status as enum ('placed', 'accepted', 'packed', 'delivered', 'cancelled');
create type public.payment_status as enum ('claimed', 'confirmed');
create type public.notification_channel as enum ('in_app', 'push', 'whatsapp', 'sms');
create type public.notification_type as enum (
  'booking_reminder',
  'order_accepted',
  'item_unavailable',
  'order_delivered',
  'payment_due',
  'payment_confirmed',
  'monthly_statement',
  'manual_reminder',
  'vendor_approved'
);
create type public.report_status as enum ('open', 'resolved', 'dismissed');

-- Prices for 'g' items are quoted per 100 g; every other unit per 1 unit.
create function public.unit_price_basis(u public.item_unit)
returns numeric
language sql immutable parallel safe
set search_path = ''
as $$ select case when u = 'g' then 100::numeric else 1::numeric end $$;

-- How much one tap of "+" adds.
create function public.default_step(u public.item_unit)
returns numeric
language sql immutable parallel safe
set search_path = ''
as $$ select case u when 'kg' then 0.25 when 'g' then 100 else 1 end::numeric $$;

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

-- One row per auth user, created by a trigger on auth.users.
create table public.users (
  id uuid primary key references auth.users (id) on delete cascade,
  phone text unique,
  name text check (char_length(name) between 1 and 80),
  role public.user_role not null default 'customer',
  language public.app_language not null default 'en',
  status public.user_status not null default 'active',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.apartments (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(btrim(name)) between 2 and 120),
  area text not null check (char_length(btrim(area)) between 2 and 120),
  city text not null default 'Bengaluru' check (char_length(city) <= 60),
  lat double precision check (lat between -90 and 90),
  lng double precision check (lng between -180 and 180),
  house_count_estimate integer check (house_count_estimate between 1 and 50000),
  created_by uuid references public.users (id) on delete set null,
  status public.apartment_status not null default 'active',
  merged_into uuid references public.apartments (id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint apartments_merge_consistent check ((status = 'merged') = (merged_into is not null)),
  constraint apartments_not_merged_into_self check (merged_into <> id)
);
create index apartments_name_trgm on public.apartments using gin (name extensions.gin_trgm_ops);
create index apartments_area_trgm on public.apartments using gin (area extensions.gin_trgm_ops);

create table public.vendors (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null unique references public.users (id) on delete cascade,
  shop_name text not null check (char_length(btrim(shop_name)) between 2 and 80),
  address text check (char_length(address) <= 300),
  shop_photo text,   -- object path in the public "shop-photos" bucket
  id_photo text,     -- object path in the private "id-photos" bucket
  upi_id text check (upi_id ~ '^[A-Za-z0-9._-]{2,128}@[A-Za-z0-9]{2,64}$'),
  service_charge numeric(8, 2) not null default 0 check (service_charge between 0 and 500),
  approval_status public.vendor_approval not null default 'pending',
  approved_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.vendor_apartments (
  vendor_id uuid not null references public.vendors (id) on delete cascade,
  apartment_id uuid not null references public.apartments (id) on delete cascade,
  delivery_window_start time not null default '07:00',
  delivery_window_end time not null default '09:00',
  payment_mode public.payment_mode not null default 'per_delivery',
  payment_method public.payment_method not null default 'upi',
  unpaid_limit numeric(10, 2) not null default 1000 check (unpaid_limit >= 0),
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (vendor_id, apartment_id),
  constraint vendor_apartments_window_order check (delivery_window_end > delivery_window_start)
);
create index vendor_apartments_apartment on public.vendor_apartments (apartment_id) where active;

create table public.households (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null unique references public.users (id) on delete cascade,
  apartment_id uuid not null references public.apartments (id),
  flat_no text not null check (char_length(btrim(flat_no)) between 1 and 20),
  block text check (char_length(block) <= 20),
  vendor_id uuid references public.vendors (id) on delete set null,
  payment_mode_override public.payment_mode,
  payment_method_override public.payment_method,
  paused boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index households_vendor on public.households (vendor_id);
create index households_apartment on public.households (apartment_id);

create table public.catalogue_items (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9-]+$'),
  name_en text not null,
  name_kn text not null,
  photo text,  -- URL or path, e.g. /veg/tomato.svg
  default_unit public.item_unit not null,
  category public.item_category not null,
  sort_order integer not null default 0,
  active boolean not null default true
);

create table public.vendor_items (
  id uuid primary key default gen_random_uuid(),
  vendor_id uuid not null references public.vendors (id) on delete cascade,
  catalogue_item_id uuid not null references public.catalogue_items (id),
  unit public.item_unit not null,
  step numeric(8, 3) not null check (step > 0),
  -- Per unit_price_basis(unit): per kg, per 100 g, per piece/bunch/packet.
  price_min numeric(8, 2) not null check (price_min > 0),
  price_max numeric(8, 2) not null,
  reason_tag public.reason_tag,
  available boolean not null default true,  -- in stock today
  listed boolean not null default true,     -- shown in the shop at all
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (vendor_id, catalogue_item_id),
  constraint vendor_items_price_range check (price_max >= price_min)
);

create table public.orders (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id),
  vendor_id uuid not null references public.vendors (id),
  apartment_id uuid not null references public.apartments (id),
  delivery_date date not null,
  status public.order_status not null default 'placed',
  service_charge numeric(8, 2) not null default 0 check (service_charge >= 0),
  est_min numeric(10, 2) not null default 0,
  est_max numeric(10, 2) not null default 0,
  final_total numeric(10, 2) check (final_total >= 0),
  placed_at timestamptz not null default now(),
  accepted_at timestamptz,
  packed_at timestamptz,
  delivered_at timestamptz,
  cancelled_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint orders_estimate_range check (est_max >= est_min)
);
-- One live order per household per delivery day.
create unique index orders_one_per_household_day
  on public.orders (household_id, delivery_date) where status <> 'cancelled';
create index orders_vendor_day on public.orders (vendor_id, delivery_date);

create table public.order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders (id) on delete cascade,
  vendor_item_id uuid not null references public.vendor_items (id),
  catalogue_item_id uuid not null references public.catalogue_items (id),
  unit_snapshot public.item_unit not null,
  qty_ordered numeric(8, 3) not null check (qty_ordered > 0),
  price_min_snapshot numeric(8, 2) not null,
  price_max_snapshot numeric(8, 2) not null,
  available boolean,  -- null until the vendor decides
  qty_actual numeric(8, 3) check (qty_actual >= 0),
  final_price numeric(8, 2),
  line_total numeric(10, 2) generated always as (
    round(qty_actual * final_price / public.unit_price_basis(unit_snapshot), 2)
  ) stored,
  unique (order_id, vendor_item_id),
  constraint order_items_final_price_in_range
    check (final_price is null or final_price between price_min_snapshot and price_max_snapshot)
);
create index order_items_order on public.order_items (order_id);

create table public.payments (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id),
  vendor_id uuid not null references public.vendors (id),
  order_id uuid references public.orders (id),  -- null for monthly settlements
  amount numeric(10, 2) not null check (amount > 0),
  method public.payment_method not null,
  status public.payment_status not null default 'claimed',
  claimed_at timestamptz not null default now(),
  confirmed_at timestamptz,
  confirmed_by uuid references public.users (id),
  note text check (char_length(note) <= 200),
  created_at timestamptz not null default now(),
  constraint payments_confirmed_consistent check ((status = 'confirmed') = (confirmed_at is not null))
);
create index payments_vendor_household on public.payments (vendor_id, household_id);

create table public.vendor_holidays (
  vendor_id uuid not null references public.vendors (id) on delete cascade,
  date date not null,
  primary key (vendor_id, date)
);

-- Channel-agnostic notification log. In-app rows double as the inbox; push,
-- WhatsApp and SMS rows record delivery attempts.
create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.users (id) on delete cascade,
  type public.notification_type not null,
  channel public.notification_channel not null default 'in_app',
  payload jsonb not null default '{}'::jsonb,  -- params for the translated message
  dedupe_key text,                             -- e.g. booking_reminder:2026-10-19
  created_at timestamptz not null default now(),
  sent_at timestamptz,
  read_at timestamptz,
  error text,
  unique (user_id, channel, dedupe_key)
);
create index notifications_user_inbox on public.notifications (user_id, created_at desc) where channel = 'in_app';

create table public.push_subscriptions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.users (id) on delete cascade,
  endpoint text not null unique,
  p256dh text not null,
  auth text not null,
  user_agent text,
  created_at timestamptz not null default now()
);
create index push_subscriptions_user on public.push_subscriptions (user_id);

create table public.reports (
  id uuid primary key default gen_random_uuid(),
  from_user uuid not null references public.users (id) on delete cascade,
  about uuid references public.users (id) on delete set null,  -- the user being reported, if any
  order_id uuid references public.orders (id) on delete set null,
  text text not null check (char_length(btrim(text)) between 1 and 2000),
  status public.report_status not null default 'open',
  created_at timestamptz not null default now(),
  resolved_at timestamptz
);


-- ===== 20261018000002_functions.sql =====
-- Time rules, role helpers and integrity triggers.

-- ---------------------------------------------------------------------------
-- The clock. In tests and the local dev stack the database-level setting
-- app.fake_now can pin it; API clients have no way to change that setting.
-- ---------------------------------------------------------------------------
create function public.app_now()
returns timestamptz
language sql stable
set search_path = ''
as $$ select coalesce(nullif(current_setting('app.fake_now', true), '')::timestamptz, now()) $$;

-- ---------------------------------------------------------------------------
-- Booking window (IST). Mirrors src/lib/time.ts; keep the two in sync.
-- Orders placed 10:00–16:59 IST are for delivery tomorrow. From 17:00 they lock.
-- The vendor must accept by 21:00 IST the evening before delivery.
-- ---------------------------------------------------------------------------
create function public.booking_state(p_at timestamptz default public.app_now())
returns table (phase text, delivery_date date, closes_at timestamptz, opens_at timestamptz)
language sql stable
set search_path = ''
as $$
  with t as (select (p_at at time zone 'Asia/Kolkata') as local)
  select
    case
      when local::time < time '10:00' then 'not_open'
      when local::time < time '17:00' then 'open'
      else 'locked'
    end,
    local::date + 1,
    case when local::time >= time '10:00' and local::time < time '17:00'
      then (local::date + time '17:00') at time zone 'Asia/Kolkata' end,
    case
      when local::time < time '10:00' then (local::date + time '10:00') at time zone 'Asia/Kolkata'
      when local::time >= time '17:00' then (local::date + 1 + time '10:00') at time zone 'Asia/Kolkata'
    end
  from t
$$;

create function public.can_customer_edit(p_delivery_date date, p_at timestamptz default public.app_now())
returns boolean
language sql stable
set search_path = ''
as $$
  select b.phase = 'open' and b.delivery_date = p_delivery_date
  from public.booking_state(p_at) b
$$;

create function public.vendor_accept_deadline(p_delivery_date date)
returns timestamptz
language sql immutable
set search_path = ''
as $$ select ((p_delivery_date - 1) + time '21:00') at time zone 'Asia/Kolkata' $$;

-- ---------------------------------------------------------------------------
-- Role helpers for RLS. SECURITY DEFINER so policies can call them without
-- recursing through each other's RLS; each only reveals facts about the caller.
-- ---------------------------------------------------------------------------
create function public.is_admin()
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.users
    where id = (select auth.uid()) and role = 'admin' and status = 'active'
  )
$$;

create function public.current_vendor_id()
returns uuid
language sql stable security definer
set search_path = ''
as $$ select id from public.vendors where user_id = (select auth.uid()) $$;

create function public.current_household_id()
returns uuid
language sql stable security definer
set search_path = ''
as $$ select id from public.households where user_id = (select auth.uid()) $$;

-- The vendor chosen by the caller's household (customers may always see it).
create function public.my_household_vendor_id()
returns uuid
language sql stable security definer
set search_path = ''
as $$ select vendor_id from public.households where user_id = (select auth.uid()) $$;

-- True if p_user_id is a customer of the calling vendor.
create function public.is_my_customer(p_user_id uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.households h
    where h.user_id = p_user_id
      and h.vendor_id = (select v.id from public.vendors v where v.user_id = (select auth.uid()))
  )
$$;

-- True if p_user_id owns the vendor the caller's household buys from.
create function public.is_my_vendor_user(p_user_id uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.households h
    join public.vendors v on v.id = h.vendor_id
    where h.user_id = (select auth.uid()) and v.user_id = p_user_id
  )
$$;

-- ---------------------------------------------------------------------------
-- Triggers
-- ---------------------------------------------------------------------------
create function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end
$$;

create trigger users_updated_at before update on public.users
  for each row execute function public.set_updated_at();
create trigger apartments_updated_at before update on public.apartments
  for each row execute function public.set_updated_at();
create trigger vendors_updated_at before update on public.vendors
  for each row execute function public.set_updated_at();
create trigger vendor_apartments_updated_at before update on public.vendor_apartments
  for each row execute function public.set_updated_at();
create trigger households_updated_at before update on public.households
  for each row execute function public.set_updated_at();
create trigger vendor_items_updated_at before update on public.vendor_items
  for each row execute function public.set_updated_at();
create trigger orders_updated_at before update on public.orders
  for each row execute function public.set_updated_at();

-- Create the profile row when someone signs in with OTP for the first time.
-- The client may pass { language: 'kn' } as user metadata on sign-up.
create function public.handle_new_auth_user()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  insert into public.users (id, phone, language)
  values (
    new.id,
    new.phone,
    case when new.raw_user_meta_data ->> 'language' = 'kn' then 'kn'::public.app_language
         else 'en'::public.app_language end
  )
  on conflict (id) do nothing;
  return new;
end
$$;

create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_auth_user();

-- Becoming a vendor: new vendor rows always start pending, and the owner's role
-- flips from customer to vendor.
create function public.handle_new_vendor()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  update public.users set role = 'vendor' where id = new.user_id and role = 'customer';
  return new;
end
$$;

create trigger on_vendor_created after insert on public.vendors
  for each row execute function public.handle_new_vendor();

-- Fill in the stepper increment from the unit when the app omits it.
create function public.vendor_items_default_step()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.step is null then
    new.step := public.default_step(new.unit);
  end if;
  return new;
end
$$;

create trigger vendor_items_default_step before insert or update of unit, step on public.vendor_items
  for each row execute function public.vendor_items_default_step();

-- A household may only pick a vendor that is approved and actively serves its apartment.
create function public.households_check_vendor()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  if new.vendor_id is not null
     and (tg_op = 'INSERT' or new.vendor_id is distinct from old.vendor_id
          or new.apartment_id is distinct from old.apartment_id)
     and not exists (
       select 1
       from public.vendor_apartments va
       join public.vendors v on v.id = va.vendor_id
       where va.vendor_id = new.vendor_id
         and va.apartment_id = new.apartment_id
         and va.active
         and v.approval_status = 'active'
     )
  then
    raise exception 'This vendor does not deliver to your apartment'
      using errcode = 'P0001', hint = 'vendor_not_serving_apartment';
  end if;
  return new;
end
$$;

create trigger households_check_vendor before insert or update on public.households
  for each row execute function public.households_check_vendor();

-- ---------------------------------------------------------------------------
-- Apartment search (search first, add if not found). Runs as the caller.
-- ---------------------------------------------------------------------------
create function public.search_apartments(p_query text, p_limit integer default 20)
returns setof public.apartments
language sql stable
set search_path = ''
as $$
  select a.*
  from public.apartments a
  where a.status = 'active'
    and (
      a.name operator(extensions.%) p_query
      or a.area operator(extensions.%) p_query
      or a.name ilike '%' || p_query || '%'
      or a.area ilike '%' || p_query || '%'
    )
  order by greatest(extensions.similarity(a.name, p_query), extensions.similarity(a.area, p_query)) desc,
           a.name
  limit least(greatest(p_limit, 1), 50)
$$;


-- ===== 20261018000003_rls.sql =====
-- Row-level security.
--
-- Principles
--  * RLS is on for every table; no policy means no access.
--  * Column grants limit WHAT a user may write; policies limit WHICH rows.
--  * Orders, order items, payments, approvals, merges and pauses are written
--    only through SECURITY DEFINER functions (added in later migrations) that
--    check the booking window and roles in IST inside the database.
--  * The service role (server-only, cron jobs) bypasses RLS.

alter table public.users enable row level security;
alter table public.apartments enable row level security;
alter table public.vendors enable row level security;
alter table public.vendor_apartments enable row level security;
alter table public.households enable row level security;
alter table public.catalogue_items enable row level security;
alter table public.vendor_items enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
alter table public.payments enable row level security;
alter table public.vendor_holidays enable row level security;
alter table public.notifications enable row level security;
alter table public.push_subscriptions enable row level security;
alter table public.reports enable row level security;

-- ---------------------------------------------------------------------------
-- Table privileges. Start from nothing, then grant precisely.
-- ---------------------------------------------------------------------------
revoke all on all tables in schema public from anon, authenticated;

grant select on public.catalogue_items to anon, authenticated;

grant select on public.users to authenticated;
grant update (name, language) on public.users to authenticated;

grant select on public.apartments to authenticated;
grant insert (id, name, area, city, lat, lng, house_count_estimate, created_by) on public.apartments to authenticated;

grant select on public.vendors to authenticated;
grant insert (id, user_id, shop_name, address, shop_photo, id_photo, upi_id, service_charge) on public.vendors to authenticated;
grant update (shop_name, address, shop_photo, id_photo, upi_id, service_charge) on public.vendors to authenticated;

grant select, insert, update, delete on public.vendor_apartments to authenticated;

grant select on public.households to authenticated;
grant insert (id, user_id, apartment_id, flat_no, block, vendor_id) on public.households to authenticated;
grant update (apartment_id, flat_no, block, vendor_id) on public.households to authenticated;

grant select, delete on public.vendor_items to authenticated;
grant insert (id, vendor_id, catalogue_item_id, unit, step, price_min, price_max, reason_tag, available, listed)
  on public.vendor_items to authenticated;
grant update (unit, step, price_min, price_max, reason_tag, available, listed)
  on public.vendor_items to authenticated;

grant select on public.orders to authenticated;
grant select on public.order_items to authenticated;
grant select on public.payments to authenticated;

grant select, insert, delete on public.vendor_holidays to authenticated;

grant select on public.notifications to authenticated;
grant update (read_at) on public.notifications to authenticated;

grant select, insert, delete on public.push_subscriptions to authenticated;

grant select on public.reports to authenticated;
grant insert (from_user, about, order_id, text) on public.reports to authenticated;

-- ---------------------------------------------------------------------------
-- users
-- ---------------------------------------------------------------------------
create policy users_select on public.users for select to authenticated
  using (
    id = (select auth.uid())
    or (select public.is_admin())
    or public.is_my_customer(id)      -- vendor sees their customers' names and phones
    or public.is_my_vendor_user(id)   -- customer sees their vendor's name and phone
  );

create policy users_update_self on public.users for update to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));

-- ---------------------------------------------------------------------------
-- apartments: anyone signed in can search and add; admin merges via function.
-- ---------------------------------------------------------------------------
create policy apartments_select on public.apartments for select to authenticated
  using (true);

create policy apartments_insert on public.apartments for insert to authenticated
  with check (created_by = (select auth.uid()));

-- ---------------------------------------------------------------------------
-- vendors: invisible to customers until approved.
-- ---------------------------------------------------------------------------
create policy vendors_select on public.vendors for select to authenticated
  using (
    user_id = (select auth.uid())
    or approval_status = 'active'
    or id = (select public.my_household_vendor_id())  -- still see a paused vendor you owe
    or (select public.is_admin())
  );

create policy vendors_insert_self on public.vendors for insert to authenticated
  with check (user_id = (select auth.uid()));

create policy vendors_update_self on public.vendors for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- ---------------------------------------------------------------------------
-- vendor_apartments
-- ---------------------------------------------------------------------------
create policy vendor_apartments_select on public.vendor_apartments for select to authenticated
  using (
    vendor_id = (select public.current_vendor_id())
    or (select public.is_admin())
    or (active and exists (
      select 1 from public.vendors v where v.id = vendor_id and v.approval_status = 'active'
    ))
  );

create policy vendor_apartments_write on public.vendor_apartments for all to authenticated
  using (vendor_id = (select public.current_vendor_id()))
  with check (vendor_id = (select public.current_vendor_id()));

-- ---------------------------------------------------------------------------
-- households
-- ---------------------------------------------------------------------------
create policy households_select on public.households for select to authenticated
  using (
    user_id = (select auth.uid())
    or vendor_id = (select public.current_vendor_id())
    or (select public.is_admin())
  );

create policy households_insert_self on public.households for insert to authenticated
  with check (user_id = (select auth.uid()));

create policy households_update_self on public.households for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- ---------------------------------------------------------------------------
-- catalogue_items: public read; admin writes with the service role.
-- ---------------------------------------------------------------------------
create policy catalogue_items_select_anon on public.catalogue_items for select to anon
  using (active);

create policy catalogue_items_select on public.catalogue_items for select to authenticated
  using (active or (select public.is_admin()));

-- ---------------------------------------------------------------------------
-- vendor_items: prices of approved vendors are visible to signed-in users.
-- ---------------------------------------------------------------------------
create policy vendor_items_select on public.vendor_items for select to authenticated
  using (
    vendor_id = (select public.current_vendor_id())
    or (select public.is_admin())
    or (listed and exists (
      select 1 from public.vendors v where v.id = vendor_id and v.approval_status = 'active'
    ))
  );

create policy vendor_items_write on public.vendor_items for all to authenticated
  using (vendor_id = (select public.current_vendor_id()))
  with check (vendor_id = (select public.current_vendor_id()));

-- ---------------------------------------------------------------------------
-- orders / order_items / payments: read-only here; written via functions.
-- ---------------------------------------------------------------------------
create policy orders_select on public.orders for select to authenticated
  using (
    household_id = (select public.current_household_id())
    or vendor_id = (select public.current_vendor_id())
    or (select public.is_admin())
  );

create policy order_items_select on public.order_items for select to authenticated
  using (exists (select 1 from public.orders o where o.id = order_id));  -- inherits orders RLS

create policy payments_select on public.payments for select to authenticated
  using (
    household_id = (select public.current_household_id())
    or vendor_id = (select public.current_vendor_id())
    or (select public.is_admin())
  );

-- ---------------------------------------------------------------------------
-- vendor_holidays: customers need them to block dates.
-- ---------------------------------------------------------------------------
create policy vendor_holidays_select on public.vendor_holidays for select to authenticated
  using (true);

create policy vendor_holidays_insert on public.vendor_holidays for insert to authenticated
  with check (vendor_id = (select public.current_vendor_id()));

create policy vendor_holidays_delete on public.vendor_holidays for delete to authenticated
  using (vendor_id = (select public.current_vendor_id()));

-- ---------------------------------------------------------------------------
-- notifications: own inbox; rows are created server-side.
-- ---------------------------------------------------------------------------
create policy notifications_select_own on public.notifications for select to authenticated
  using (user_id = (select auth.uid()));

create policy notifications_mark_read on public.notifications for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- ---------------------------------------------------------------------------
-- push_subscriptions
-- ---------------------------------------------------------------------------
create policy push_subscriptions_own on public.push_subscriptions for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- ---------------------------------------------------------------------------
-- reports
-- ---------------------------------------------------------------------------
create policy reports_select on public.reports for select to authenticated
  using (from_user = (select auth.uid()) or (select public.is_admin()));

create policy reports_insert_self on public.reports for insert to authenticated
  with check (from_user = (select auth.uid()));

-- ---------------------------------------------------------------------------
-- Function privileges: helpers are for signed-in users only.
-- ---------------------------------------------------------------------------
revoke execute on all functions in schema public from public, anon;
grant execute on function public.app_now() to anon, authenticated;
grant execute on function public.booking_state(timestamptz) to anon, authenticated;
grant execute on function public.can_customer_edit(date, timestamptz) to authenticated;
grant execute on function public.vendor_accept_deadline(date) to authenticated;
grant execute on function public.search_apartments(text, integer) to authenticated;
grant execute on function public.unit_price_basis(public.item_unit) to anon, authenticated;
grant execute on function public.default_step(public.item_unit) to anon, authenticated;
grant execute on function public.is_admin() to authenticated;
grant execute on function public.current_vendor_id() to authenticated;
grant execute on function public.current_household_id() to authenticated;
grant execute on function public.my_household_vendor_id() to authenticated;
grant execute on function public.is_my_customer(uuid) to authenticated;
grant execute on function public.is_my_vendor_user(uuid) to authenticated;


-- ===== 20261018000004_storage.sql =====
-- Photo storage. Object names are "<auth user id>/<file>" so ownership is the
-- first folder of the path.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('catalogue', 'catalogue', true, 2097152, array['image/jpeg', 'image/png', 'image/webp', 'image/svg+xml']),
  ('shop-photos', 'shop-photos', true, 5242880, array['image/jpeg', 'image/png', 'image/webp']),
  ('id-photos', 'id-photos', false, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

-- catalogue: public read (bucket is public); only admins write.
create policy catalogue_admin_write on storage.objects for all to authenticated
  using (bucket_id = 'catalogue' and (select public.is_admin()))
  with check (bucket_id = 'catalogue' and (select public.is_admin()));

-- shop-photos: public read; vendors manage files in their own folder.
create policy shop_photos_owner_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'shop-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy shop_photos_owner_update on storage.objects for update to authenticated
  using (bucket_id = 'shop-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy shop_photos_owner_delete on storage.objects for delete to authenticated
  using (bucket_id = 'shop-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);

-- id-photos: private; only the vendor who uploaded it and admins can view.
create policy id_photos_owner_or_admin_select on storage.objects for select to authenticated
  using (
    bucket_id = 'id-photos'
    and ((storage.foldername(name))[1] = (select auth.uid())::text or (select public.is_admin()))
  );
create policy id_photos_owner_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'id-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy id_photos_owner_update on storage.objects for update to authenticated
  using (bucket_id = 'id-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy id_photos_owner_delete on storage.objects for delete to authenticated
  using (bucket_id = 'id-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);


-- ===== 20261019000001_aliases_invites.sql =====
-- List-to-cart and WhatsApp invites.

-- ---------------------------------------------------------------------------
-- Other names for each item (spellings, Kannada in English letters, Hindi),
-- used to match typed or spoken lists such as "eerulli 2 kg, dhaniya 1".
-- ---------------------------------------------------------------------------
alter table public.catalogue_items add column aliases text[] not null default '{}';

-- ---------------------------------------------------------------------------
-- Invite links shared into existing WhatsApp groups.
--   /j/<vendor_apartments.invite_code>  join this vendor at this apartment
--   /j/<apartments.invite_code>         join this apartment, then pick a vendor
-- Codes are unguessable but harmless: they reveal only public names.
-- ---------------------------------------------------------------------------
create function public.new_invite_code()
returns text
language sql volatile
set search_path = ''
as $$ select substr(replace(gen_random_uuid()::text, '-', ''), 1, 10) $$;

alter table public.vendor_apartments
  add column invite_code text not null unique default public.new_invite_code();
alter table public.apartments
  add column invite_code text not null unique default public.new_invite_code();

-- Lets a vendor get a fresh link if an old one was shared too widely.
grant update (invite_code) on public.vendor_apartments to authenticated;

-- What a join page may show before the visitor has signed in.
create function public.resolve_invite(p_code text)
returns table (
  kind text,
  apartment_id uuid,
  apartment_name text,
  apartment_area text,
  vendor_id uuid,
  shop_name text,
  shop_photo text
)
language sql stable security definer
set search_path = ''
as $$
  select 'vendor', a.id, a.name, a.area, v.id, v.shop_name, v.shop_photo
  from public.vendor_apartments va
  join public.vendors v on v.id = va.vendor_id
  join public.apartments a on a.id = va.apartment_id
  where va.invite_code = p_code
    and va.active
    and v.approval_status = 'active'
    and a.status = 'active'
  union all
  select 'apartment', a.id, a.name, a.area, null, null, null
  from public.apartments a
  where a.invite_code = p_code and a.status = 'active'
  limit 1
$$;

-- Column defaults run as the inserting user, so signed-in users need this.
revoke execute on function public.new_invite_code() from public, anon;
grant execute on function public.new_invite_code() to authenticated;
revoke execute on function public.resolve_invite(text) from public;
grant execute on function public.resolve_invite(text) to anon, authenticated;


-- ===== 20261019000002_operations.sql =====
-- Everything customers, vendors and admins DO. Each function checks who is
-- calling and the IST booking window inside the database, then writes with
-- definer rights; RLS keeps direct table writes closed.
--
-- Errors are raised as P0001 with a short machine code in the message
-- (e.g. 'booking_closed'); the app turns codes into translated text.

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------
create function public.fail(p_code text)
returns void
language plpgsql
set search_path = ''
as $$ begin raise exception '%', p_code using errcode = 'P0001'; end $$;

-- The calling user, if signed in and not blocked.
create function public.require_active_user()
returns uuid
language plpgsql stable security definer
set search_path = ''
as $$
declare uid uuid := auth.uid();
begin
  if uid is null then perform public.fail('not_signed_in'); end if;
  if exists (select 1 from public.users where id = uid and status = 'blocked') then perform public.fail('account_blocked'); end if;
  return uid;
end $$;

-- The calling vendor's id; must be approved unless p_allow_pending.
create function public.require_vendor(p_allow_pending boolean default false)
returns uuid
language plpgsql stable security definer
set search_path = ''
as $$
declare v record;
begin
  perform public.require_active_user();
  select id, approval_status into v from public.vendors where user_id = auth.uid();
  if v.id is null then perform public.fail('not_a_vendor'); end if;
  if v.approval_status = 'blocked' then perform public.fail('vendor_blocked'); end if;
  if not p_allow_pending and v.approval_status <> 'active' then perform public.fail('vendor_not_active'); end if;
  return v.id;
end $$;

create function public.require_admin()
returns void
language plpgsql stable security definer
set search_path = ''
as $$
begin
  perform public.require_active_user();
  if not public.is_admin() then perform public.fail('not_admin'); end if;
end $$;

-- Estimate (and, once packed, final total) of one order.
create function public.recompute_order(p_order_id uuid)
returns void
language sql security definer
set search_path = ''
as $$
  update public.orders o set
    est_min = o.service_charge + coalesce((
      select sum(oi.qty_ordered * oi.price_min_snapshot / public.unit_price_basis(oi.unit_snapshot))
      from public.order_items oi where oi.order_id = o.id and oi.available is distinct from false), 0),
    est_max = o.service_charge + coalesce((
      select sum(oi.qty_ordered * oi.price_max_snapshot / public.unit_price_basis(oi.unit_snapshot))
      from public.order_items oi where oi.order_id = o.id and oi.available is distinct from false), 0),
    final_total = case when o.status in ('packed', 'delivered') then o.service_charge + coalesce((
      select sum(oi.line_total) from public.order_items oi where oi.order_id = o.id and oi.available), 0) end
  where o.id = p_order_id
$$;

-- When orders for a delivery date stop changing: 17:00 IST the day before.
create function public.orders_lock_at(p_delivery_date date)
returns timestamptz
language sql immutable
set search_path = ''
as $$ select ((p_delivery_date - 1) + time '17:00') at time zone 'Asia/Kolkata' $$;

-- ---------------------------------------------------------------------------
-- Customer
-- ---------------------------------------------------------------------------

-- Replaces the caller's order for the open delivery date with p_items:
-- [{ "vendor_item_id": uuid, "qty": number }]. An empty list cancels it.
create function public.place_order(p_items jsonb)
returns uuid
language plpgsql security definer
set search_path = ''
as $$
declare
  h public.households;
  v public.vendors;
  b record;
  o public.orders;
  wanted int;
  added int;
begin
  perform public.require_active_user();
  select * into h from public.households where user_id = auth.uid();
  if h.id is null then perform public.fail('no_household'); end if;
  if h.vendor_id is null then perform public.fail('no_vendor'); end if;
  if h.paused then perform public.fail('household_paused'); end if;

  select * into v from public.vendors where id = h.vendor_id;
  if v.approval_status <> 'active' then perform public.fail('vendor_unavailable'); end if;
  if not exists (select 1 from public.vendor_apartments va
                 where va.vendor_id = v.id and va.apartment_id = h.apartment_id and va.active) then
    perform public.fail('vendor_unavailable');
  end if;

  select * into b from public.booking_state();
  if b.phase <> 'open' then perform public.fail('booking_closed'); end if;
  if exists (select 1 from public.vendor_holidays where vendor_id = v.id and date = b.delivery_date) then
    perform public.fail('vendor_holiday');
  end if;

  select * into o from public.orders
  where household_id = h.id and delivery_date = b.delivery_date and status <> 'cancelled'
  for update;
  if o.id is not null and o.status <> 'placed' then perform public.fail('order_locked'); end if;

  wanted := coalesce(jsonb_array_length(p_items), 0);
  if wanted = 0 then
    if o.id is not null then
      update public.orders set status = 'cancelled', cancelled_at = now() where id = o.id;
    end if;
    return null;
  end if;
  if wanted > 60 then perform public.fail('too_many_items'); end if;

  if o.id is null then
    insert into public.orders (household_id, vendor_id, apartment_id, delivery_date, service_charge)
    values (h.id, v.id, h.apartment_id, b.delivery_date, v.service_charge)
    returning * into o;
  else
    update public.orders set service_charge = v.service_charge, apartment_id = h.apartment_id where id = o.id;
    delete from public.order_items where order_id = o.id;
  end if;

  insert into public.order_items (order_id, vendor_item_id, catalogue_item_id, unit_snapshot, qty_ordered,
                                  price_min_snapshot, price_max_snapshot)
  select o.id, vi.id, vi.catalogue_item_id, vi.unit, (e ->> 'qty')::numeric, vi.price_min, vi.price_max
  from jsonb_array_elements(p_items) e
  join public.vendor_items vi on vi.id = (e ->> 'vendor_item_id')::uuid
  where vi.vendor_id = v.id and vi.listed and vi.available
    and (e ->> 'qty')::numeric > 0 and (e ->> 'qty')::numeric <= 10000;
  get diagnostics added = row_count;
  if added <> wanted then perform public.fail('item_unavailable'); end if;

  perform public.recompute_order(o.id);
  return o.id;
end $$;

create function public.cancel_my_order(p_order_id uuid)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare o public.orders;
begin
  perform public.require_active_user();
  select * into o from public.orders
  where id = p_order_id and household_id = public.current_household_id() for update;
  if o.id is null then perform public.fail('order_not_found'); end if;
  if o.status <> 'placed' or not public.can_customer_edit(o.delivery_date) then perform public.fail('order_locked'); end if;
  update public.orders set status = 'cancelled', cancelled_at = now() where id = o.id;
end $$;

-- "I've paid" (UPI) or "I paid in cash". The vendor confirms later.
create function public.claim_payment(p_amount numeric, p_method public.payment_method, p_order_id uuid default null)
returns uuid
language plpgsql security definer
set search_path = ''
as $$
declare h public.households; pid uuid;
begin
  perform public.require_active_user();
  select * into h from public.households where user_id = auth.uid();
  if h.id is null or h.vendor_id is null then perform public.fail('no_vendor'); end if;
  if p_amount is null or p_amount <= 0 or p_amount > 100000 then perform public.fail('bad_amount'); end if;
  if p_order_id is not null and not exists (
    select 1 from public.orders where id = p_order_id and household_id = h.id and status = 'delivered') then
    perform public.fail('order_not_found');
  end if;
  insert into public.payments (household_id, vendor_id, order_id, amount, method, status)
  values (h.id, h.vendor_id, p_order_id, round(p_amount, 2), p_method, 'claimed')
  returning id into pid;
  return pid;
end $$;

-- Billed (delivered orders) minus confirmed payments, per household and vendor.
create function public.household_ledger(p_household_id uuid, p_vendor_id uuid)
returns table (billed numeric, paid numeric, claimed numeric, balance numeric, oldest_unpaid date)
language sql stable security definer
set search_path = ''
as $$
  with billed as (
    select coalesce(sum(final_total), 0) amt, min(delivery_date) first_date
    from public.orders where household_id = p_household_id and vendor_id = p_vendor_id and status = 'delivered'
  ), pay as (
    select coalesce(sum(amount) filter (where status = 'confirmed'), 0) confirmed,
           coalesce(sum(amount) filter (where status = 'claimed'), 0) claimed
    from public.payments where household_id = p_household_id and vendor_id = p_vendor_id
  ), unpaid as (
    -- Oldest delivered order not yet covered by confirmed payments (first-in, first-out).
    select min(delivery_date) d from (
      select delivery_date, sum(final_total) over (order by delivery_date, id) running
      from public.orders where household_id = p_household_id and vendor_id = p_vendor_id and status = 'delivered'
    ) x where running > (select confirmed from pay)
  )
  select billed.amt, pay.confirmed, pay.claimed, billed.amt - pay.confirmed, unpaid.d
  from billed, pay, unpaid
$$;

create function public.my_ledger()
returns table (billed numeric, paid numeric, claimed numeric, balance numeric, oldest_unpaid date)
language sql stable security definer
set search_path = ''
as $$
  select l.* from public.households h, public.household_ledger(h.id, h.vendor_id) l
  where h.user_id = auth.uid() and h.vendor_id is not null
$$;

-- ---------------------------------------------------------------------------
-- Vendor
-- ---------------------------------------------------------------------------

-- Accepts every placed order for a delivery date once booking has locked.
-- Items not explicitly unticked become available.
create function public.vendor_accept_orders(p_delivery_date date)
returns integer
language plpgsql security definer
set search_path = ''
as $$
declare vid uuid := public.require_vendor(); n int;
begin
  if public.app_now() < public.orders_lock_at(p_delivery_date) then perform public.fail('booking_still_open'); end if;
  update public.order_items oi set available = true
  from public.orders o
  where oi.order_id = o.id and o.vendor_id = vid and o.delivery_date = p_delivery_date
    and o.status = 'placed' and oi.available is null;
  update public.orders set status = 'accepted', accepted_at = now()
  where vendor_id = vid and delivery_date = p_delivery_date and status = 'placed';
  get diagnostics n = row_count;
  return n;
end $$;

-- Tick / untick one item of a locked order (before it is packed).
create function public.vendor_set_item_available(p_order_item_id uuid, p_available boolean)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare vid uuid := public.require_vendor(); o public.orders;
begin
  select o2.* into o from public.orders o2 join public.order_items oi on oi.order_id = o2.id
  where oi.id = p_order_item_id and o2.vendor_id = vid for update of o2;
  if o.id is null then perform public.fail('order_not_found'); end if;
  if o.status not in ('placed', 'accepted') then perform public.fail('order_locked'); end if;
  if public.app_now() < public.orders_lock_at(o.delivery_date) then perform public.fail('booking_still_open'); end if;
  update public.order_items set available = p_available,
    qty_actual = case when p_available then qty_actual else null end,
    final_price = case when p_available then final_price else null end
  where id = p_order_item_id;
  perform public.recompute_order(o.id);
end $$;

-- Saves weights and prices: [{ "order_item_id", "qty_actual", "final_price" }]
-- and marks the order packed. Prices must sit inside each item's range.
create function public.vendor_pack_order(p_order_id uuid, p_items jsonb)
returns numeric
language plpgsql security definer
set search_path = ''
as $$
declare vid uuid := public.require_vendor(); o public.orders; total numeric;
begin
  select * into o from public.orders where id = p_order_id and vendor_id = vid for update;
  if o.id is null then perform public.fail('order_not_found'); end if;
  if o.status not in ('accepted', 'packed') then perform public.fail('order_not_accepted'); end if;

  update public.order_items oi set
    qty_actual = (e ->> 'qty_actual')::numeric,
    final_price = (e ->> 'final_price')::numeric
  from jsonb_array_elements(p_items) e
  where oi.id = (e ->> 'order_item_id')::uuid and oi.order_id = o.id and oi.available;

  if exists (select 1 from public.order_items where order_id = o.id and available
             and (qty_actual is null or final_price is null)) then
    perform public.fail('items_not_weighed');
  end if;

  update public.orders set status = 'packed', packed_at = coalesce(packed_at, now()) where id = o.id;
  perform public.recompute_order(o.id);
  select final_total into total from public.orders where id = o.id;
  return total;
end $$;

create function public.vendor_mark_delivered(p_order_id uuid)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare vid uuid := public.require_vendor();
begin
  update public.orders set status = 'delivered', delivered_at = now()
  where id = p_order_id and vendor_id = vid and status = 'packed';
  if not found then perform public.fail('order_not_packed'); end if;
end $$;

-- Dues for every household that buys from the caller.
create function public.vendor_dues()
returns table (household_id uuid, user_id uuid, name text, phone text, apartment_id uuid, block text, flat_no text,
               paused boolean, billed numeric, paid numeric, claimed numeric, balance numeric, oldest_unpaid date,
               pending_payment_id uuid, pending_amount numeric, pending_method public.payment_method)
language sql stable security definer
set search_path = ''
as $$
  select h.id, u.id, u.name, u.phone, h.apartment_id, h.block, h.flat_no, h.paused,
         l.billed, l.paid, l.claimed, l.balance, l.oldest_unpaid,
         p.id, p.amount, p.method
  from public.households h
  join public.users u on u.id = h.user_id
  cross join lateral public.household_ledger(h.id, h.vendor_id) l
  left join lateral (
    select id, amount, method from public.payments
    where household_id = h.id and vendor_id = h.vendor_id and status = 'claimed'
    order by created_at limit 1
  ) p on true
  where h.vendor_id = public.require_vendor(true)
$$;

create function public.vendor_confirm_payment(p_payment_id uuid)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare vid uuid := public.require_vendor();
begin
  update public.payments set status = 'confirmed', confirmed_at = now(), confirmed_by = auth.uid()
  where id = p_payment_id and vendor_id = vid and status = 'claimed';
  if not found then perform public.fail('payment_not_found'); end if;
end $$;

-- "Not received": the claim is removed; the balance stays owed.
create function public.vendor_reject_payment(p_payment_id uuid)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare vid uuid := public.require_vendor();
begin
  delete from public.payments where id = p_payment_id and vendor_id = vid and status = 'claimed';
  if not found then perform public.fail('payment_not_found'); end if;
end $$;

create function public.vendor_record_cash(p_household_id uuid, p_amount numeric)
returns uuid
language plpgsql security definer
set search_path = ''
as $$
declare vid uuid := public.require_vendor(); pid uuid;
begin
  if not exists (select 1 from public.households where id = p_household_id and vendor_id = vid) then
    perform public.fail('not_your_customer');
  end if;
  if p_amount is null or p_amount <= 0 or p_amount > 100000 then perform public.fail('bad_amount'); end if;
  insert into public.payments (household_id, vendor_id, amount, method, status, confirmed_at, confirmed_by)
  values (p_household_id, vid, round(p_amount, 2), 'cash', 'confirmed', now(), auth.uid())
  returning id into pid;
  return pid;
end $$;

create function public.vendor_set_household_paused(p_household_id uuid, p_paused boolean)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare vid uuid := public.require_vendor(true);
begin
  update public.households set paused = p_paused where id = p_household_id and vendor_id = vid;
  if not found then perform public.fail('not_your_customer'); end if;
end $$;

create function public.vendor_set_household_terms(p_household_id uuid, p_mode public.payment_mode, p_method public.payment_method)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare vid uuid := public.require_vendor(true);
begin
  update public.households set payment_mode_override = p_mode, payment_method_override = p_method
  where id = p_household_id and vendor_id = vid;
  if not found then perform public.fail('not_your_customer'); end if;
end $$;

create function public.vendor_reset_invite(p_apartment_id uuid)
returns text
language plpgsql security definer
set search_path = ''
as $$
declare vid uuid := public.require_vendor(true); code text := public.new_invite_code();
begin
  update public.vendor_apartments set invite_code = code where vendor_id = vid and apartment_id = p_apartment_id;
  if not found then perform public.fail('not_your_apartment'); end if;
  return code;
end $$;

-- ---------------------------------------------------------------------------
-- Admin
-- ---------------------------------------------------------------------------
create function public.admin_set_vendor_status(p_vendor_id uuid, p_status public.vendor_approval)
returns void
language plpgsql security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  update public.vendors set approval_status = p_status,
    approved_at = case when p_status = 'active' then coalesce(approved_at, now()) else approved_at end
  where id = p_vendor_id;
  if not found then perform public.fail('vendor_not_found'); end if;
end $$;

create function public.admin_set_user_status(p_user_id uuid, p_status public.user_status)
returns void
language plpgsql security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  if p_user_id = auth.uid() then perform public.fail('cannot_block_self'); end if;
  update public.users set status = p_status where id = p_user_id;
  if not found then perform public.fail('user_not_found'); end if;
end $$;

-- Moves households and vendor links from a duplicate into the surviving apartment.
create function public.admin_merge_apartments(p_from uuid, p_into uuid)
returns void
language plpgsql security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  if p_from = p_into then perform public.fail('same_apartment'); end if;
  if not exists (select 1 from public.apartments where id = p_into and status = 'active') then perform public.fail('apartment_not_found'); end if;
  update public.households set apartment_id = p_into where apartment_id = p_from;
  insert into public.vendor_apartments (vendor_id, apartment_id, delivery_window_start, delivery_window_end,
                                        payment_mode, payment_method, unpaid_limit, active)
  select vendor_id, p_into, delivery_window_start, delivery_window_end, payment_mode, payment_method, unpaid_limit, active
  from public.vendor_apartments where apartment_id = p_from
  on conflict (vendor_id, apartment_id) do nothing;
  delete from public.vendor_apartments where apartment_id = p_from;
  update public.apartments set status = 'merged', merged_into = p_into where id = p_from;
end $$;

create function public.admin_remove_apartment(p_id uuid)
returns void
language plpgsql security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  update public.apartments set status = 'removed' where id = p_id and status = 'active';
  if not found then perform public.fail('apartment_not_found'); end if;
end $$;

create function public.admin_set_report_status(p_report_id uuid, p_status public.report_status)
returns void
language plpgsql security definer
set search_path = ''
as $$
begin
  perform public.require_admin();
  update public.reports set status = p_status,
    resolved_at = case when p_status = 'open' then null else now() end
  where id = p_report_id;
end $$;

-- ---------------------------------------------------------------------------
-- In-app notifications created by the database itself, so no code path can
-- forget them. The server sends the matching web push (src/lib/notify).
-- ---------------------------------------------------------------------------
create function public.notify(p_user_id uuid, p_type public.notification_type, p_payload jsonb, p_dedupe text)
returns void
language sql security definer
set search_path = ''
as $$
  insert into public.notifications (user_id, type, channel, payload, dedupe_key)
  values (p_user_id, p_type, 'in_app', p_payload, p_dedupe)
  on conflict (user_id, channel, dedupe_key) do nothing
$$;

create function public.orders_notify()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare uid uuid;
begin
  select user_id into uid from public.households where id = new.household_id;
  if new.status = 'accepted' and old.status = 'placed' then
    perform public.notify(uid, 'order_accepted', jsonb_build_object('orderId', new.id, 'deliveryDate', new.delivery_date), 'accepted:' || new.id);
  elsif new.status = 'delivered' and old.status <> 'delivered' then
    perform public.notify(uid, 'order_delivered',
      jsonb_build_object('orderId', new.id, 'deliveryDate', new.delivery_date, 'amount', new.final_total), 'delivered:' || new.id);
  end if;
  return new;
end $$;
create trigger orders_notify after update of status on public.orders
  for each row execute function public.orders_notify();

create function public.order_items_notify()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare uid uuid; oid uuid; dd date;
begin
  if new.available = false and old.available is distinct from false then
    select h.user_id, o.id, o.delivery_date into uid, oid, dd
    from public.orders o join public.households h on h.id = o.household_id where o.id = new.order_id;
    perform public.notify(uid, 'item_unavailable',
      jsonb_build_object('orderId', oid, 'deliveryDate', dd, 'catalogueItemId', new.catalogue_item_id), 'unavailable:' || new.id);
  end if;
  return new;
end $$;
create trigger order_items_notify after update of available on public.order_items
  for each row execute function public.order_items_notify();

create function public.vendors_notify()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  if new.approval_status = 'active' and old.approval_status <> 'active' then
    perform public.notify(new.user_id, 'vendor_approved', '{}'::jsonb, 'approved:' || new.id || ':' || now()::date);
  end if;
  return new;
end $$;
create trigger vendors_notify after update of approval_status on public.vendors
  for each row execute function public.vendors_notify();

create function public.payments_notify()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare uid uuid;
begin
  if new.status = 'confirmed' and (tg_op = 'INSERT' or old.status <> 'confirmed') then
    select user_id into uid from public.households where id = new.household_id;
    perform public.notify(uid, 'payment_confirmed', jsonb_build_object('amount', new.amount), 'paid:' || new.id);
  end if;
  return new;
end $$;
create trigger payments_notify after insert or update of status on public.payments
  for each row execute function public.payments_notify();

-- ---------------------------------------------------------------------------
-- Privileges: helpers stay internal; app operations are for signed-in users.
-- ---------------------------------------------------------------------------
revoke execute on function public.fail(text), public.require_active_user(), public.require_vendor(boolean),
  public.require_admin(), public.recompute_order(uuid), public.household_ledger(uuid, uuid),
  public.notify(uuid, public.notification_type, jsonb, text), public.orders_notify(), public.order_items_notify(),
  public.vendors_notify(), public.payments_notify()
  from public, anon, authenticated;

revoke execute on function public.orders_lock_at(date), public.place_order(jsonb), public.cancel_my_order(uuid),
  public.claim_payment(numeric, public.payment_method, uuid), public.my_ledger(),
  public.vendor_accept_orders(date), public.vendor_set_item_available(uuid, boolean), public.vendor_pack_order(uuid, jsonb),
  public.vendor_mark_delivered(uuid), public.vendor_dues(), public.vendor_confirm_payment(uuid), public.vendor_reject_payment(uuid),
  public.vendor_record_cash(uuid, numeric), public.vendor_set_household_paused(uuid, boolean),
  public.vendor_set_household_terms(uuid, public.payment_mode, public.payment_method), public.vendor_reset_invite(uuid),
  public.admin_set_vendor_status(uuid, public.vendor_approval), public.admin_set_user_status(uuid, public.user_status),
  public.admin_merge_apartments(uuid, uuid), public.admin_remove_apartment(uuid), public.admin_set_report_status(uuid, public.report_status)
  from public, anon;

grant execute on function public.orders_lock_at(date), public.place_order(jsonb), public.cancel_my_order(uuid),
  public.claim_payment(numeric, public.payment_method, uuid), public.my_ledger(),
  public.vendor_accept_orders(date), public.vendor_set_item_available(uuid, boolean), public.vendor_pack_order(uuid, jsonb),
  public.vendor_mark_delivered(uuid), public.vendor_dues(), public.vendor_confirm_payment(uuid), public.vendor_reject_payment(uuid),
  public.vendor_record_cash(uuid, numeric), public.vendor_set_household_paused(uuid, boolean),
  public.vendor_set_household_terms(uuid, public.payment_mode, public.payment_method), public.vendor_reset_invite(uuid),
  public.admin_set_vendor_status(uuid, public.vendor_approval), public.admin_set_user_status(uuid, public.user_status),
  public.admin_merge_apartments(uuid, uuid), public.admin_remove_apartment(uuid), public.admin_set_report_status(uuid, public.report_status)
  to authenticated;


-- ===== 20261019000003_vendor_remind.sql =====
-- Vendor sends a payment reminder to one household (at most once a day each).
create function public.vendor_remind(p_household_id uuid)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare vid uuid := public.require_vendor(); h public.households; bal numeric;
begin
  select * into h from public.households where id = p_household_id and vendor_id = vid;
  if h.id is null then perform public.fail('not_your_customer'); end if;
  select l.balance - l.claimed into bal from public.household_ledger(h.id, vid) l;
  if coalesce(bal, 0) <= 0 then return; end if;
  perform public.notify(h.user_id, 'manual_reminder', jsonb_build_object('amount', bal),
    'remind:' || h.id || ':' || (public.app_now() at time zone 'Asia/Kolkata')::date);
end $$;

revoke execute on function public.vendor_remind(uuid) from public, anon;
grant execute on function public.vendor_remind(uuid) to authenticated;


-- ===== 20261019000004_reminders.sql =====
-- Scheduled reminders. Called by the Vercel Cron routes with the service role;
-- each writes in-app notifications (deduped, so re-running is harmless) and
-- returns how many it created. The app then pushes them (src/lib/notify/push.ts).

alter type public.notification_type add value if not exists 'accept_reminder';

-- 15:30 IST: customers with a vendor who haven't ordered for tomorrow yet.
create function public.cron_booking_reminders()
returns integer
language plpgsql security definer
set search_path = ''
as $$
declare b record; n int;
begin
  select * into b from public.booking_state();
  if b.phase <> 'open' then return 0; end if;
  insert into public.notifications (user_id, type, channel, payload, dedupe_key)
  select h.user_id, 'booking_reminder', 'in_app', jsonb_build_object('deliveryDate', b.delivery_date),
         'booking:' || b.delivery_date
  from public.households h
  join public.users u on u.id = h.user_id and u.status = 'active'
  join public.vendors v on v.id = h.vendor_id and v.approval_status = 'active'
  where not h.paused
    and not exists (select 1 from public.vendor_holidays vh where vh.vendor_id = v.id and vh.date = b.delivery_date)
    and not exists (select 1 from public.orders o where o.household_id = h.id and o.delivery_date = b.delivery_date and o.status <> 'cancelled')
  on conflict (user_id, channel, dedupe_key) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;

-- 19:00 IST: vendors who still have orders to accept for tomorrow (deadline 21:00).
create function public.cron_accept_reminders()
returns integer
language plpgsql security definer
set search_path = ''
as $$
declare d date := (public.app_now() at time zone 'Asia/Kolkata')::date + 1; n int;
begin
  insert into public.notifications (user_id, type, channel, payload, dedupe_key)
  select v.user_id, 'accept_reminder', 'in_app', jsonb_build_object('deliveryDate', d, 'count', count(*)), 'accept:' || d
  from public.orders o join public.vendors v on v.id = o.vendor_id
  where o.delivery_date = d and o.status = 'placed'
  group by v.user_id
  on conflict (user_id, channel, dedupe_key) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;

-- 18:00 IST: per-delivery customers with an unpaid balance (one nudge a day at most,
-- and only once a bill is at least a day old).
create function public.cron_payment_due()
returns integer
language plpgsql security definer
set search_path = ''
as $$
declare today date := (public.app_now() at time zone 'Asia/Kolkata')::date; n int;
begin
  insert into public.notifications (user_id, type, channel, payload, dedupe_key)
  select h.user_id, 'payment_due', 'in_app', jsonb_build_object('amount', l.balance - l.claimed), 'due:' || h.id || ':' || today
  from public.households h
  join public.vendor_apartments va on va.vendor_id = h.vendor_id and va.apartment_id = h.apartment_id
  cross join lateral public.household_ledger(h.id, h.vendor_id) l
  where coalesce(h.payment_mode_override, va.payment_mode) = 'per_delivery'
    and l.balance - l.claimed > 0
    and l.oldest_unpaid < today
  on conflict (user_id, channel, dedupe_key) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;

-- 1st of the month, 09:00 IST: monthly-bill customers get their statement.
create function public.cron_monthly_statements()
returns integer
language plpgsql security definer
set search_path = ''
as $$
declare month text := to_char(public.app_now() at time zone 'Asia/Kolkata', 'YYYY-MM'); n int;
begin
  insert into public.notifications (user_id, type, channel, payload, dedupe_key)
  select h.user_id, 'monthly_statement', 'in_app', jsonb_build_object('amount', l.balance - l.claimed), 'monthly:' || h.id || ':' || month
  from public.households h
  join public.vendor_apartments va on va.vendor_id = h.vendor_id and va.apartment_id = h.apartment_id
  cross join lateral public.household_ledger(h.id, h.vendor_id) l
  where coalesce(h.payment_mode_override, va.payment_mode) = 'monthly'
    and l.balance - l.claimed > 0
  on conflict (user_id, channel, dedupe_key) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;

revoke execute on function public.cron_booking_reminders(), public.cron_accept_reminders(),
  public.cron_payment_due(), public.cron_monthly_statements() from public, anon, authenticated;
grant execute on function public.cron_booking_reminders(), public.cron_accept_reminders(),
  public.cron_payment_due(), public.cron_monthly_statements() to service_role;


